            aOrbiterA = (aWandererE + RotL64(aScatter, 23U)) + 0xE5E1F54BC070A552ULL;
            aOrbiterK = (aWandererI + RotL64(aIngress, 57U)) + 0xC9558238B770F316ULL;
            aOrbiterG = ((aWandererA + RotL64(aCross, 29U)) + 0x98C336DA245D7663ULL) + aNonceWordP;
            aOrbiterF = (((aWandererC + RotL64(aPrevious, 13U)) + RotL64(aCarry, 5U)) + 0x5944C5DCDA8A8448ULL) + aNonceWordH;
            aOrbiterB = ((((aWandererJ + RotL64(aIngress, 42U)) + RotL64(aCarry, 37U)) + 0xBFBF60465360E8CFULL) + aSeedOrbiterAssignSaltE[(((255U - aIndex) + 197U)) & S_SALT1]) + aNonceWordI;
