            aWandererF = aWandererF ^ (((RotL64(aPrevious, 39U) + aOrbiterA) + RotL64(aOrbiterC, 56U)) + aSeedWandererUpdateSaltE[(((255U - aIndex) + 14U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aCross, 60U) + aOrbiterG) + RotL64(aOrbiterC, 11U));
